package com.brightloop.subscription;
import java.time.LocalDate;import java.util.List;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.Lock;import org.springframework.data.jpa.repository.Query;import jakarta.persistence.LockModeType;
public interface SubscriptionRepository extends JpaRepository<Subscription,Long>{List<Subscription> findByCustomerId(Long customerId);List<Subscription> findByStatusAndNextBillingDateBetween(String status,LocalDate from,LocalDate to);long countByStatus(String status);long countByStatusAndNextBillingDateBetween(String status,LocalDate from,LocalDate to);@Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select s from Subscription s where s.status='ACTIVE' and s.nextBillingDate <= :today and (s.expiryDate is null or s.expiryDate >= :today)") List<Subscription> findDueForBilling(LocalDate today);@Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select s from Subscription s where s.status='ACTIVE' and s.expiryDate < :today") List<Subscription> findExpiredActive(LocalDate today);@Query("select coalesce(sum(case when s.billingFrequency=com.brightloop.plan.BillingFrequency.MONTHLY then (s.subtotal-s.discountAmount) when s.billingFrequency=com.brightloop.plan.BillingFrequency.YEARLY then (s.subtotal-s.discountAmount) / 12 when s.billingFrequency=com.brightloop.plan.BillingFrequency.WEEKLY then (s.subtotal-s.discountAmount) * 52 / 12 else (s.subtotal-s.discountAmount) * 30 end),0) from Subscription s where s.status='ACTIVE'") java.math.BigDecimal calculateMrr();@Query("select p.name, count(s) from Subscription s join s.plan p where s.status='ACTIVE' group by p.name") List<Object[]> activeSubscriptionsByPlan();}
